<?php
/**
 * Faithful Witness — Custom Admin Menu
 *
 * Adds a "Faithful Witness" top-level menu in the WordPress sidebar
 * with quick links to the most common content management tasks.
 *
 * ADMIN NOTE: This file controls the admin sidebar menu shortcuts.
 * Do not edit this file. Content is managed via the admin forms.
 */

if ( ! defined( 'ABSPATH' ) ) exit;

// ============================================================
// REGISTER THE TOP-LEVEL MENU
// ============================================================
add_action( 'admin_menu', 'fw_register_admin_menu' );
function fw_register_admin_menu() {
    // Top-level dashboard page
    add_menu_page(
        __( 'Faithful Witness', 'faithfulwitness' ),
        __( 'Faithful Witness', 'faithfulwitness' ),
        'edit_posts',
        'faithfulwitness-hub',
        'fw_admin_dashboard_page',
        fw_admin_menu_icon(),
        3 // position — near top of sidebar
    );

    // Dashboard (same as parent)
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Dashboard', 'faithfulwitness' ),
        __( 'Dashboard', 'faithfulwitness' ),
        'edit_posts',
        'faithfulwitness-hub',
        'fw_admin_dashboard_page'
    );

    // Add a Resource
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Add a Resource', 'faithfulwitness' ),
        __( '+ Add a Resource', 'faithfulwitness' ),
        'publish_posts',
        'fw-add-resource',
        'fw_admin_redirect_page'
    );

    // Add an Event
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Add an Event', 'faithfulwitness' ),
        __( '+ Add an Event', 'faithfulwitness' ),
        'publish_posts',
        'fw-add-event',
        'fw_admin_redirect_page'
    );

    // Add a Media Hit
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Add a Media Hit', 'faithfulwitness' ),
        __( '+ Add a Media Hit', 'faithfulwitness' ),
        'publish_posts',
        'fw-add-media-hit',
        'fw_admin_redirect_page'
    );

    // Add a Story
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Add a Story', 'faithfulwitness' ),
        __( '+ Add a Story', 'faithfulwitness' ),
        'publish_posts',
        'fw-add-story',
        'fw_admin_redirect_page'
    );

    // Update Network Partners
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Network Partners', 'faithfulwitness' ),
        __( 'Network Partners', 'faithfulwitness' ),
        'edit_posts',
        'fw-partners',
        'fw_admin_redirect_page'
    );

    // Admin Guides
    add_submenu_page(
        'faithfulwitness-hub',
        __( 'Admin Guides', 'faithfulwitness' ),
        __( 'Admin Guides', 'faithfulwitness' ),
        'edit_posts',
        'fw-admin-guides',
        'fw_admin_redirect_page'
    );
}

// ============================================================
// HANDLE REDIRECTS FOR SHORTCUT SUBMENUS
// ============================================================
add_action( 'admin_init', 'fw_handle_admin_redirects' );
function fw_handle_admin_redirects() {
    if ( ! isset( $_GET['page'] ) ) return;

    $redirects = [
        'fw-add-resource'  => admin_url( 'post-new.php?post_type=fw_resource' ),
        'fw-add-event'     => admin_url( 'post-new.php?post_type=fw_event' ),
        'fw-add-media-hit' => admin_url( 'post-new.php?post_type=fw_media_hit' ),
        'fw-add-story'     => admin_url( 'post-new.php?post_type=post' ),
        'fw-partners'      => admin_url( 'edit.php?post_type=fw_organizing_group' ),
        'fw-admin-guides'  => fw_get_admin_guide_url(),
    ];

    $page = sanitize_key( $_GET['page'] );
    if ( isset( $redirects[ $page ] ) ) {
        wp_safe_redirect( $redirects[ $page ] );
        exit;
    }
}

/** Get the URL of the admin guide index. */
function fw_get_admin_guide_url() {
    $guide = get_page_by_path( 'admin-guide-content-management', OBJECT, 'page' );
    return $guide ? get_edit_post_link( $guide->ID ) : admin_url( 'edit.php?post_type=page&s=Admin+Guide' );
}

/** Callback for redirect submenus — never actually renders. */
function fw_admin_redirect_page() {}

