// ============================================================
// MENU ICON — custom SVG cross/dove
// ============================================================
function fw_admin_menu_icon() {
    // Base64 encoded SVG: simple dove/peace symbol
    $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor"><path d="M10 2a8 8 0 100 16A8 8 0 0010 2zm0 14a6 6 0 110-12 6 6 0 010 12zm-1-9h2v4H9V7zm0 5h2v2H9v-2z"/></svg>';
    return 'data:image/svg+xml;base64,' . base64_encode( $svg );
}
